import gzip
import json
import math
from collections.abc import Mapping
from copy import deepcopy


def batch_items(items, size, strict=False):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(size, bool) or not isinstance(size, int):
        raise TypeError("size must be an integer")
    if size <= 0:
        raise ValueError("size must be positive")
    if not isinstance(strict, bool):
        raise TypeError("strict must be a bool")
    copied = deepcopy(items)
    return [copied[index:index + size] for index in range(0, len(copied), size)]


def unbatch_items(batches):
    if not isinstance(batches, list):
        raise TypeError("batches must be a list")
    if any(not isinstance(batch, list) for batch in batches):
        raise TypeError("every batch must be a list")
    return deepcopy([item for batch in batches for item in batch])


def first_items(batches):
    if not isinstance(batches, list):
        raise TypeError("batches must be a list")
    result = []
    for batch in batches:
        if not isinstance(batch, list):
            raise TypeError("every batch must be a list")
        if not batch:
            raise ValueError("batches must not be empty")
        result.append(deepcopy(batch[0]))
    return result


def columns_to_records(columns):
    if not isinstance(columns, Mapping):
        raise TypeError("columns must be a mapping")
    snapshot = deepcopy(dict(columns))
    for name, values in snapshot.items():
        if not isinstance(name, str):
            raise TypeError("column names must be strings")
        if not name:
            raise ValueError("column names must be non-empty")
        if not isinstance(values, list):
            raise TypeError("column values must be lists")
    lengths = {len(values) for values in snapshot.values()}
    if len(lengths) > 1:
        raise ValueError("columns have unequal lengths")
    count = next(iter(lengths), 0)
    return [{name: snapshot[name][index] for name in snapshot} for index in range(count)]


def quantile_positions(length, parts):
    if isinstance(length, bool) or not isinstance(length, int):
        raise TypeError("length must be an integer")
    if isinstance(parts, bool) or not isinstance(parts, int):
        raise TypeError("parts must be an integer")
    if length < 0:
        raise ValueError("length must be non-negative")
    if parts < 2:
        raise ValueError("parts must be at least two")
    if length == 0:
        return []
    return [math.floor(k * (length - 1) / (parts - 1)) for k in range(parts)]


def encode_records(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")
    if any(not isinstance(record, dict) for record in records):
        raise TypeError("records must contain dictionaries")
    try:
        text = "".join(
            json.dumps(
                record,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                allow_nan=False,
            ) + "\n"
            for record in deepcopy(records)
        )
    except (TypeError, ValueError) as exc:
        raise TypeError("records are not JSON-compatible") from exc
    return gzip.compress(text.encode("utf-8"), mtime=0)


def _reject_json_constant(value):
    raise ValueError(f"invalid JSON constant: {value}")


def decode_records(data):
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError("data must be bytes-like")
    try:
        text = gzip.decompress(bytes(data)).decode("utf-8")
    except (OSError, EOFError, UnicodeDecodeError) as exc:
        raise ValueError("invalid compressed data") from exc
    if not text:
        return []
    lines = text.splitlines()
    if any(not line.strip() for line in lines):
        raise ValueError("blank JSON Lines rows are not allowed")
    result = []
    try:
        for line in lines:
            value = json.loads(line, parse_constant=_reject_json_constant)
            if not isinstance(value, dict):
                raise ValueError("every row must be a dictionary")
            result.append(value)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON Lines data") from exc
    return result

